  ('95de4aa7-e219-5165-8e87-0c1d3db9bfa4', 'casa-da-carla-pet-house', '589b4c60-1528-5e6f-ae15-942ed1e17da2', 'Casa da Carla Pet House', 'autonomo', 'Hospedagem domiciliar, creche e passeios com rotina de casa', 'Sou a Carla, veterinária de formação e apaixonada por cães e gatos. Há 7 anos recebo pets na minha casa em Passo Fundo como se fossem da família: quintal telado, rotina de passeios, alimentação no horário do tutor e fotos todos os dias. Atendo no máximo 6 hóspedes por vez para garantir atenção individual. Antes da primeira hospedagem faço uma visita de adaptação gratuita.', array['hospedagem', 'creche', 'passeio', 'pet_sitter']::text[], 'passo-fundo-rs', 'Vila Rodrigues', -28.288, -52.401, 11, 7, 4.71, 94, array[0, 5, 6, 0, 83]::integer[], 6, 0.921, true, true, true, 7, 368, array['cao', 'gato']::text[], array['mini', 'pequeno', 'medio', 'grande', 'gigante']::text[], 3000, true, '+5554983375700', '[{"day":0,"open":"09:00","close":"18:00"},{"day":1,"open":"07:30","close":"18:30"},{"day":2,"open":"07:30","close":"18:30"},{"day":3,"open":"07:30","close":"18:30"},{"day":4,"open":"07:30","close":"18:30"},{"day":5,"open":"07:30","close":"18:30"},{"day":6,"open":"08:00","close":"13:00"}]'::jsonb, array['Quintal telado 120 m²', 'Câmera para o tutor', 'Fotos diárias no WhatsApp', 'Sem gaiolas', 'Ar-condicionado no inverno', 'Área separada para gatos', 'Táxi dog']::text[], 'moderada', 'pro', true, 'publicado', true, pg_temp.ts('2023-01-04T02:35:44.545Z')),
