  ('9a50239a-45a7-5020-a425-ce1be74d02ff', null, 'pedido_recebido', 'Pedido recebido', 'utility', 'Olá, {{nome}}! Recebemos seu pedido de {{servico}} para {{pet}} em {{data}} às {{hora}}. {{prestador}} vai responder em breve. Protocolo {{codigo}}.', '{}'::text[], true),
  ('ca245b26-f5e6-501c-8b79-2dff68ee13a9', null, 'confirmacao_agendamento', 'Pedir confirmação', 'utility', 'Oi, {{nome}}! {{prestador}} aceitou o agendamento de {{servico}} para {{pet}} em {{data}} às {{hora}}. Toque em *Confirmar* para garantir sua vaga. 🐾', array['Confirmar', 'Remarcar', 'Cancelar']::text[], true),
  ('36454aff-5347-50fc-8699-6c1159b7db1c', null, 'lembrete_24h', 'Lembrete 24 h', 'utility', 'Lembrete: amanhã às {{hora}} tem {{servico}} do {{pet}} com {{prestador}}. Qualquer imprevisto, é só responder aqui.', array['Estarei lá', 'Preciso remarcar']::text[], true),
  ('a3a26565-5247-5db5-a76e-15b6272518ed', null, 'pos_atendimento_avaliacao', 'Pedir avaliação', 'utility', '{{pet}} já está pronto(a)! Obrigado por confiar em {{prestador}}. Conta pra gente como foi? Sua avaliação ajuda outros tutores.', array['Avaliar agora']::text[], true),
  ('26a46c4e-d284-5e35-81c6-676b6cb6aa55', null, 'vaga_liberada', 'Vaga liberada', 'marketing', 'Oi, {{nome}}! Abriu uma vaga de {{servico}} em {{data}} às {{hora}}. Quer garantir para o {{pet}}?', array['Quero a vaga', 'Agora não']::text[], true),
  ('9b0f9408-9b3a-5526-b6b6-d7c27db55ad6', null, 'saudade_reativacao', 'Reativar cliente', 'marketing', 'Oi, {{nome}}! Faz um tempinho que o {{pet}} não vem nos visitar. Que tal agendar esta semana? Temos horários livres. 🐶', array['Agendar', 'Parar de receber']::text[], true),
  ('56f6aa0d-a472-5f10-ab5c-da30e4e2e108', null, 'saldo_pacote', 'Saldo do pacote', 'utility', '{{nome}}, seu pacote "{{pacote}}" tem {{saldo}} sessões restantes, válidas até {{validade}}.', '{}'::text[], false);
