  ('16ae7307-7ac9-5451-90b8-1b6db1c1cad1', '95de4aa7-e219-5165-8e87-0c1d3db9bfa4', '93d56e0e-e533-5659-aef6-c1047a56d809', '+5554981118785', 'novo', array['lead', 'gato']::text[], 1, pg_temp.ts('2026-11-04T02:32:44.545Z'), 'Olá! Vocês aceitam gatos para hospedagem? Viajo dia 20.', pg_temp.ts('2026-11-04T02:32:44.545Z'), null, pg_temp.ts('2026-11-04T02:47:44.545Z'), null),
