  ('faab4f2e-e18f-5e58-bb3b-492dd8b17042', '95de4aa7-e219-5165-8e87-0c1d3db9bfa4', '9a291e91-a954-52b9-8742-3e486f06d1a1', '+5554981174218', 'resolvido', array['perdido']::text[], 0, pg_temp.ts('2026-10-30T06:05:44.545Z'), 'Tudo bem, Roberto! Quando quiser é só chamar 🙂', pg_temp.ts('2026-10-30T05:55:44.545Z'), null, null, null);
