  ('5eb510c8-7412-510a-81f0-3370c7039c56', '1bca0fcf-18fa-58ae-8b6d-a7010cb667f4', '95de4aa7-e219-5165-8e87-0c1d3db9bfa4', 'cliente', 'Estarei lá', pg_temp.ts('2026-11-03T16:55:44.545Z'), 'lido', null, null),
